static situ_err_t fzn_settings_registry_node_cell(uint32_t cell,
		const uint8_t *data, uint32_t len, int64_t *value, int *has_value)
{
	situ_msg_t  msg;
	situ_view_t view;
	situ_err_t  e;

	*has_value = 0;
	*value     = 0;
	situ_msg_init(&msg, (uint8_t *)(uintptr_t)data, len);
	switch (cell) {
	case 0u: /* count */
		e = fzn_settings_registry_count_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_count_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		{
			uint64_t held = 0;

			e = fzn_settings_registry_count_value_get(view, &held);
			if (e != SITU_OK) {
				return e;
			}
			*value = (int64_t)held;
		}
		*has_value = 1;
		return SITU_OK;
	case 1u: /* text */
		e = fzn_settings_registry_text_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_text_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		return SITU_OK;
	case 2u: /* duration */
		e = fzn_settings_registry_duration_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_duration_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		*value     = (int64_t)fzn_settings_registry_duration_value_get(view);
		*has_value = 1;
		return SITU_OK;
	case 3u: /* flag */
		e = fzn_settings_registry_flag_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_flag_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		*value     = (int64_t)fzn_settings_registry_flag_value_get(view);
		*has_value = 1;
		return SITU_OK;
	case 4u: /* address */
		e = fzn_settings_registry_address_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_address_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		return SITU_OK;
	case 5u: /* pressure_rank */
		e = fzn_settings_registry_pressure_rank_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_pressure_rank_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		return SITU_OK;
	case 6u: /* log_level */
		e = fzn_settings_registry_log_level_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_log_level_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		return SITU_OK;
	case 7u: /* log_scope */
		e = fzn_settings_registry_log_scope_view(&msg, 0u, len, &view);
		if (e != SITU_OK) {
			return e;
		}
		e = fzn_settings_registry_log_scope_validate(view);
		if (e != SITU_OK) {
			return e;
		}
		return SITU_OK;
	default:
		return SITU_ERR_CONSTRAINT;
	}
}

static int fzn_settings_registry_node_same(const uint8_t *a, const char *b, uint32_t n)
{
	for (uint32_t i = 0u; i < n; i++) {
		if (a[i] != (uint8_t)b[i]) {
			return 0;
		}
	}
	return 1;
}

const fzn_settings_registry_node_entry_t *fzn_settings_registry_node_find(const uint8_t *key, uint32_t len)
{
	if (key == NULL) {
		return NULL;
	}
	for (uint32_t i = 0u; i < FZN_SETTINGS_REGISTRY_NODE_COUNT; i++) {
		const fzn_settings_registry_node_entry_t *e = &fzn_settings_registry_node_entries[i];

		if (!e->family) {
			if (len == e->key_len && fzn_settings_registry_node_same(key, e->key, len)) {
				return e;
			}
			continue;
		}
		/* A family's instance: the key, then one word. */
		if (len <= e->key_len || !fzn_settings_registry_node_same(key, e->key, e->key_len)) {
			continue;
		}
		uint32_t at = e->key_len;
		for (; at < len; at++) {
			if (!((key[at] >= 'a' && key[at] <= 'z')
			      || (key[at] >= '0' && key[at] <= '9'))) {
				break;
			}
		}
		if (at == len) {
			return e;
		}
	}
	return NULL;
}

situ_err_t fzn_settings_registry_node_check(const fzn_settings_registry_node_entry_t *entry,
		const uint8_t *value, uint32_t len)
{
	int64_t    held = 0;
	int        has  = 0;
	situ_err_t e;

	if (entry == NULL || (value == NULL && len != 0u)) {
		return SITU_ERR_CONSTRAINT;
	}
	if (len < entry->min_size || len > entry->max_size) {
		return SITU_ERR_CONSTRAINT;
	}
	e = fzn_settings_registry_node_cell(entry->cell, value, len, &held, &has);
	if (e != SITU_OK) {
		return e;
	}
	if (has && ((entry->has_min && held < entry->min)
	            || (entry->has_max && held > entry->max))) {
		return SITU_ERR_CONSTRAINT;
	}
	return SITU_OK;
}

situ_err_t fzn_settings_registry_node_value(const fzn_settings_registry_node_entry_t *entry,
		const uint8_t *value, uint32_t len, int64_t *out)
{
	int64_t    held = 0;
	int        has  = 0;
	situ_err_t e;

	if (out == NULL) {
		return SITU_ERR_CONSTRAINT;
	}
	e = fzn_settings_registry_node_check(entry, value, len);
	if (e != SITU_OK) {
		return e;
	}
	(void)fzn_settings_registry_node_cell(entry->cell, value, len, &held, &has);
	if (!has) {
		return SITU_ERR_CONSTRAINT;
	}
	*out = held;
	return SITU_OK;
}

int fzn_settings_registry_node_safer(const fzn_settings_registry_node_entry_t *entry,
		const uint8_t *a, uint32_t a_len,
		const uint8_t *b, uint32_t b_len)
{
	int64_t first = 0, second = 0;

	if (entry == NULL || entry->safe == 0u
	    || fzn_settings_registry_node_value(entry, a, a_len, &first) != SITU_OK
	    || fzn_settings_registry_node_value(entry, b, b_len, &second) != SITU_OK) {
		return 0;
	}
	return entry->safe == FZN_SETTINGS_REGISTRY_SAFE_LOWER ? second < first : second > first;
}

